<?php
require_once __DIR__.'/includes/appointment_helpers.php';
if(!is_logged_in()||($_SESSION['role']??'')!=='doctor'){header('Location: login.php');exit;}$doctorId=(int)$_SESSION['user_id'];if(!doctor_is_approved($pdo,$doctorId)){http_response_code(403);exit('Not approved.');}$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=filter_var($_POST['appointment_id']??null,FILTER_VALIDATE_INT);$action=$_POST['action']??'';$s=$pdo->prepare('SELECT * FROM appointments WHERE id=? AND doctor_id=?');$s->execute([$id,$doctorId]);$a=$s->fetch();
 if(!$a)$errors[]='Appointment not found.';
 elseif($action==='confirm'||$action==='reject'){if($a['status']!=='pending')$errors[]='Only pending requests can be confirmed or rejected.';else{$status=$action==='confirm'?'confirmed':'rejected';$u=$pdo->prepare('UPDATE appointments SET status=? WHERE id=? AND doctor_id=? AND status="pending"');$u->execute([$status,$id,$doctorId]);flash('Appointment '.$status.'.');header('Location: doctor_appointments.php');exit;}}
 elseif($action==='reschedule'){if(!in_array($a['status'],['confirmed','rescheduled'],true))$errors[]='Only confirmed appointments can be rescheduled.';else{$date=(string)($_POST['new_date']??'');$time=(string)($_POST['new_time']??'');if(!is_valid_future_date($date)||!preg_match('/^(?:[01]\d|2[0-3]):[0-5]\d$/',$time))$errors[]='Choose a valid date and time.';else try{$pdo->beginTransaction();$l=$pdo->prepare('SELECT id FROM users WHERE id=? FOR UPDATE');$l->execute([$doctorId]);$l->fetch();$t=$time.':00';if(!time_is_in_doctor_availability($pdo,$doctorId,$date,$t))throw new RuntimeException('That time is outside your availability.');$c=$pdo->prepare('SELECT id FROM appointments WHERE doctor_id=? AND appointment_date=? AND appointment_time=? AND status IN ("pending","confirmed","rescheduled") AND id<>?');$c->execute([$doctorId,$date,$t,$id]);if($c->fetch())throw new RuntimeException('That slot is already occupied.');$u=$pdo->prepare('UPDATE appointments SET appointment_date=?,appointment_time=?,status="rescheduled" WHERE id=? AND doctor_id=?');$u->execute([$date,$t,$id,$doctorId]);$pdo->commit();flash('Appointment rescheduled.');header('Location: doctor_appointments.php');exit;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$errors[]=$e instanceof RuntimeException?$e->getMessage():'Rescheduling failed.';}}}
}
$s=$pdo->prepare('SELECT a.*,u.full_name patient_name,u.email patient_email FROM appointments a JOIN users u ON u.id=a.patient_id WHERE a.doctor_id=? ORDER BY a.appointment_date,a.appointment_time');$s->execute([$doctorId]);$rows=$s->fetchAll();$notice=get_flash();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Appointment requests | MediConnect</title><link rel="stylesheet" href="assets/css/auth.css"></head><body><main class="dashboard-shell"><header class="dashboard-header"><a class="brand" href="doctor_dashboard.php">✚ MediConnect</a><a href="doctor_availability.php">My availability</a></header><section class="welcome-panel"><h1>Appointment requests</h1></section><?php if($notice):?><div class="alert success"><?=e($notice['message'])?></div><?php endif;?><?php if($errors):?><div class="alert error"><?php foreach($errors as $x):?><p><?=e($x)?></p><?php endforeach;?></div><?php endif;?><?php if(!$rows):?><section class="profile-panel">No requests received.</section><?php endif;?><?php foreach($rows as $a):?><article class="profile-panel"><div class="appointment-heading"><h2><?=e($a['patient_name'])?></h2><span class="status"><?=e(ucfirst($a['status']))?></span></div><p><?=e($a['patient_email'])?></p><p><b><?=e(date('D, j M Y',strtotime($a['appointment_date'])))?> at <?=e(date('g:i A',strtotime($a['appointment_time'])))?></b></p><p><b>Reason:</b> <?=e($a['symptoms'])?></p><?php if($a['status']==='pending'):?><div class="action-row"><?php foreach(['confirm'=>'Confirm','reject'=>'Reject'] as $act=>$label):?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="appointment_id" value="<?=(int)$a['id']?>"><input type="hidden" name="action" value="<?=$act?>"><button class="<?=$act==='confirm'?'primary-button':'secondary-button'?>"><?=$label?></button></form><?php endforeach;?></div><?php endif;?><?php if(in_array($a['status'],['confirmed','rescheduled'],true)):?><details><summary>Reschedule</summary><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="appointment_id" value="<?=(int)$a['id']?>"><input type="hidden" name="action" value="reschedule"><label>New date<input type="date" name="new_date" min="<?=e((new DateTime('today'))->format('Y-m-d'))?>" required></label><label>New time<input type="time" name="new_time" required></label><button class="secondary-button">Save reschedule</button></form></details><?php endif;?></article><?php endforeach;?></main></body></html>
